    if(tab==='dependents'){if(obj.type==='QUESTION')return`<span class="eyebrow">DEPENDENTS & COVERAGE</span><div class="aperture-list">${arr(r.model_node_ids).map(x=>`<button data-open-object="${esc(x)}"><strong>${esc(x)}</strong><small>Mapped model object</small></button>`).join('')||'<p>No model bindings are declared.</p>'}${arr(r.claim_ids).map(x=>`<button data-open-object="${esc(x)}"><strong>${esc(x)}</strong><small>Evidence or support object</small></button>`).join('')}</div>`;if(obj.type==='ARTIFACT')return`<span class="eyebrow">BINDING MAP</span><div class="aperture-list">${arr(r.trace_ids).map(x=>`<button data-open-object="${esc(x)}"><strong>${esc(x)}</strong><small>Represented object</small></button>`).join('')||'<p>No bindings declared.</p>'}</div>`;if(obj.type==='TRANSITION')return`<span class="eyebrow">AFFECTED SET</span><h3>${esc(r.disposition)}</h3><p>${esc(r.explanation)}</p><div class="before-after large"><del>${esc(r.before)}</del><i>→</i><b>${esc(r.after)}</b></div>`;return`<span class="eyebrow">DEPENDENCIES</span><pre>${esc(JSON.stringify(r,null,2))}</pre>`}
