  function drawer(state){if(!state.drawerObjectId)return'';const obj=objectLookup(state,state.drawerObjectId);if(!obj)return`<div class="drawer-backdrop" data-action="close-drawer"></div><aside class="object-drawer open" role="dialog" aria-modal="true" aria-labelledby="aperture-title"><header><div><span class="eyebrow">OBJECT APERTURE</span><h2 id="aperture-title">Unsupported object</h2></div><button class="icon-btn" data-action="close-drawer" aria-label="Close Object Aperture">${ico('close')}</button></header>${empty('Object projection unavailable','The object exists in a reference but is not included in the current frontend projection.')}</aside>`;return`<div class="drawer-backdrop" data-action="close-drawer"></div><aside class="object-drawer open" role="dialog" aria-modal="true" aria-labelledby="aperture-title"><header><div><span class="eyebrow">OBJECT APERTURE · ${esc(obj.type)}</span><h2 id="aperture-title">${esc(obj.title)}</h2></div><button class="icon-btn" data-action="close-drawer" aria-label="Close Object Aperture">${ico('close')}</button></header><nav class="aperture-tabs" role="tablist" aria-label="Object views">${[['basis','Basis'],['dependents','Dependents'],['action','Action'],['history','History']].map(([id,label])=>`<button role="tab" aria-selected="${state.drawerTab===id}" aria-controls="aperture-panel" class="${state.drawerTab===id?'active':''}" data-drawer-tab="${id}">${label}</button>`).join('')}</nav><div id="aperture-panel" role="tabpanel" class="drawer-body">${apertureBody(state,obj)}</div></aside>`}
  function commandDialog(state){if(!state.commandOpen)return'';return`<div class="modal-backdrop" data-action="close-command"></div><section class="command-dialog" role="dialog" aria-modal="true" aria-labelledby="command-title"><header><span>${ico('search')}</span><label class="sr-only" for="command-input">Search rooms and loaded objects</label><input id="command-input" data-focus-key="command-input" value="${esc(state.commandQuery)}" placeholder="Search rooms, questions, unknowns and artifacts" autocomplete="off" role="combobox" aria-controls="command-results" aria-expanded="true"><button class="icon-btn" data-action="close-command" aria-label="Close quick navigation">${ico('close')}</button></header><h2 id="command-title" class="sr-only">Quick navigation</h2><div id="command-results" role="listbox" class="command-results">${arr(state.commandResults).map((r,i)=>`<button role="option" data-command-index="${i}"><span>${esc(r.type)}</span><strong>${esc(r.label)}</strong><em>Open</em></button>`).join('')||'<p>Type to search the loaded projection. Results are never pre-injected.</p>'}</div></section>`}
