  function captureFocus(){const active=document.activeElement,scroller=document.querySelector('.workspace-content');return{key:active?.dataset?.focusKey||active?.getAttribute?.('data-action')||active?.getAttribute?.('data-view')||null,scrollTop:scroller?.scrollTop||0,scrollLeft:scroller?.scrollLeft||0}}
