    document.querySelectorAll('[data-action]').forEach(el=>el.onclick=async e=>{const x=el.dataset.action;if(x==='toggle-nav')A.toggleNav();else if(x==='toggle-action-rail')A.toggleActionRail();else if(x==='toggle-inspector')A.toggleInspector();else if(x==='toggle-motion')A.setReducedMotion();else if(x==='open-command')A.command('');else if(x==='close-command')A.closeCommand();else if(x==='close-drawer')A.closeDrawer();else if(x==='close-evidence-review')A.closeEvidenceReview();else if(x==='open-change-arrival')A.showChangeArrival();else if(x==='start-review')A.startReview();else if(x==='edit-treatment')A.editTreatment();else if(x==='cancel-treatment-edit')A.cancelEdit();else if(x==='reject-treatment')A.rejectTreatment();else if(x==='admit-treatment')A.admitTreatment();else if(x==='replay-transition')A.replayTransition();else if(x==='skip-transition')A.skipTransition();else if(x==='open-action-frontier')A.openActionFrontier();else if(x==='select-all-changes')A.selectAllChanges();else if(x==='prepare-response')A.prepareResponse();else if(x==='attest-decision')A.attestDecision();else if(x==='send-execution')A.sendExecution(false);else if(x==='simulate-failure')A.sendExecution(true);else if(x==='settle-current')A.settleCurrent();else if(x==='clear-error')A.clearError();else if(x==='new-session')A.newDemoSession();else if(x==='reset-interface')A.resetInterface();else if(x==='refresh-projection')A.refreshProjection();else if(x==='refresh-sources')A.refreshSources();else if(x==='refresh-inbox')A.refreshInbox();else if(x==='refresh-journal')A.refreshJournal();else if(x==='admit-all-pending')A.admitAllPending();else if(x==='export-sources')A.exportJSON('panta_sources.json',state.sources);else if(x==='export-claims')A.exportJSON('panta_claims_filtered.json',A.getClaims());else if(x==='export-registry')A.exportJSON('panta_registry.json',state.registry);else if(x==='export-journal')A.exportJSON(`panta_journal_${state.caseId||'case'}.json`,state.journal)});
