    const drop=document.getElementById('drop-zone');if(drop){drop.ondragover=e=>{e.preventDefault();drop.classList.add('drag')};drop.ondragleave=()=>drop.classList.remove('drag');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('drag');const files=e.dataTransfer.files;if(files?.length)A.ingestFiles(files,'Dropped source batch')}}
    const od=document.getElementById('open-deal-form');if(od)od.onsubmit=e=>{e.preventDefault();const f=new FormData(od);A.saveOpenDeal(Object.fromEntries(f))};
