  function trapDialog(root,event){if(event.key!=='Tab')return;const items=[...root.querySelectorAll('button:not([disabled]),input:not([disabled]),textarea:not([disabled]),select:not([disabled]),[tabindex]:not([tabindex="-1"])')];if(!items.length)return;const first=items[0],last=items[items.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}
  const regionCache=new Map();
  function patchRegion(id,html){const node=document.getElementById(id);if(!node)return false;if(regionCache.get(id)===html)return false;node.innerHTML=html;regionCache.set(id,html);return true}
  function ensureShell(state){let root=document.getElementById('panta-shell-root');if(root)return root;app.innerHTML=`<div id="panta-shell-root" class="v19-shell ${state.actionRailOpen?'with-action':'without-action'} ${state.reducedMotion?'reduced-motion':''}"><div id="rail-region" class="render-region"></div><section class="workspace"><div id="mode-region" class="render-region"></div><div id="topbar-region" class="render-region"></div><main id="main-content" class="workspace-content" aria-busy="false"></main><div id="causal-region" class="render-region"></div></section><div id="action-region" class="render-region"></div><div id="inspector-region" class="render-region"></div></div>`;regionCache.clear();return document.getElementById('panta-shell-root')}
  function render(state){const prior=captureFocus(),root=ensureShell(state);root.className=`v19-shell ${state.actionRailOpen?'with-action':'without-action'} ${state.reducedMotion?'reduced-motion':''}`;patchRegion('rail-region',rail(state));patchRegion('mode-region',modeStrip(state));patchRegion('topbar-region',topbar(state));const main=document.getElementById('main-content'),mainHtml=`${state.lastError?errorCard(state.lastError):''}${content(state)}`;if(regionCache.get('main-content')!==mainHtml){main.innerHTML=mainHtml;regionCache.set('main-content',mainHtml)}main.setAttribute('aria-busy',state.busy?'true':'false');patchRegion('causal-region',causalRail(state));patchRegion('action-region',actionRail(state));patchRegion('inspector-region',inspector(state));drawerRoot.innerHTML=drawer(state);modalRoot.innerHTML=commandDialog(state);toastRoot.innerHTML=state.toast?`<div class="toast ${cls(state.toast.type)}" role="status">${esc(state.toast.message)}</div>`:'';document.body.dataset.view=state.view;document.body.dataset.mode=state.mode;document.body.classList.toggle('mobile-read-only',state.mobileReadOnly);bind(state);restoreFocus(state,prior)}
  S.subscribe(render);
  document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();A.command('')}if(e.key==='Escape'){if(S.get().commandOpen)A.closeCommand();else if(S.get().drawerObjectId)A.closeDrawer();else if(S.get().navOpen)A.toggleNav()}const dialog=document.querySelector('.command-dialog,.object-drawer.open');if(dialog)trapDialog(dialog,e);if(e.shiftKey&&e.key.toLowerCase()==='i')A.toggleInspector()});
  window.PantaRender={render,objectLookup};
